insert into public.topics (slug, title, description, image_url, position, is_published)
insert into public.quiz_questions (topic_slug, quiz_type, prompt, options, correct_index, explanation, source_slide, position)
values
  ('redes-sociales', 'optional', '¿Qué conviene revisar en los ajustes de una cuenta social?', jsonb_build_array('Que cualquier persona pueda consultar la ubicación.', 'Quién ve las publicaciones y cuándo se comparte la ubicación.', 'Que todas las cuentas usen la misma contraseña.', 'Que el perfil muestre todos los horarios de la semana.'), 1, 'Controlar quién accede a las publicaciones y a la ubicación puede reducir la exposición de datos.', 2, 1),
  ('redes-sociales', 'optional', 'Una propuesta en línea viene con presión para guardar secretos y decidir hoy. ¿Qué respuesta es más prudente?', jsonb_build_array('Aceptar antes de que la oferta desaparezca.', 'Enviar documentos para confirmar que eres una persona real.', 'Detenerse y hablar con alguien de confianza antes de responder.', 'Concertar una cita para averiguar quién hizo la propuesta.'), 2, 'Frenar y pedir otra perspectiva evita tomar una decisión bajo presión o exponerse a una reunión.', 4, 2),
  ('redes-sociales', 'optional', '¿Una conducta inusual basta para concluir que existe trata?', jsonb_build_array('Sí; una oferta atractiva siempre lo demuestra.', 'Sí; cualquier mensaje de una cuenta nueva lo demuestra.', 'No; conviene considerar el contexto y los posibles patrones de control o explotación.', 'No; la explotación nunca empieza con una conversación digital.'), 2, 'Un hecho aislado no es prueba; conviene atender al contexto.', 3, 3),
  ('redes-sociales', 'required', '¿Cuál es una buena medida para reforzar el acceso a tus cuentas?', jsonb_build_array('Repetir una contraseña fácil en todos los sitios.', 'Activar un segundo paso de acceso si la plataforma lo permite.', 'Enviar la contraseña a alguien que la solicite por mensaje.', 'Compartir una foto de un documento en el perfil.'), 1, 'El segundo paso añade una comprobación al iniciar sesión, además de la contraseña.', 2, 1),
  ('redes-sociales', 'required', '¿Qué se recomienda hacer con una propuesta que exige secreto y una decisión inmediata?', jsonb_build_array('Aceptar para no perderla.', 'Enviar los documentos antes de pedir consejo.', 'Hacer una pausa y comentarla con alguien de confianza.', 'Ir a encontrarse con quien la envió.'), 2, 'Pedir apoyo antes de decidir ayuda a no actuar bajo presión ni exponerse a una cita.', 4, 2),
  ('redes-sociales', 'required', '¿Qué puede indicar que alguien intenta controlar una conversación o relación?', jsonb_build_array('Respeta que la otra persona tarde en responder.', 'Insiste en aislar, guardar secretos o decidir con urgencia.', 'Acepta que la otra persona termine la conversación.', 'Sugiere revisar la privacidad de la cuenta.'), 1, 'Aislar, imponer secretos y presionar para decidir son conductas que justifican frenar y pedir una segunda opinión.', 3, 3),
  ('redes-sociales', 'required', '¿Qué dato sería mejor no publicar mientras ocurre?', jsonb_build_array('Una reseña general de una película.', 'Una imagen de una receta sin datos personales.', 'Tu ubicación y el horario que sigues cada día.', 'Un saludo sin etiquetar a otras personas.'), 2, 'La ubicación y la rutina pueden exponer dónde está una persona y en qué momentos.', 2, 4),
  ('redes-sociales', 'required', 'Si te preocupa una conversación, ¿qué registro podrías conservar si es seguro?', jsonb_build_array('Fechas, capturas, enlaces y nombres de usuario.', 'Las claves de acceso de otras cuentas.', 'Reenviar cualquier imagen privada a tus amistades.', 'Publicar los datos familiares de quien escribió.'), 0, 'Un registro limitado puede servir al pedir apoyo; no se deben redistribuir imágenes íntimas ni exponer más datos.', 4, 5),
  ('redes-sociales', 'required', '¿Quién es responsable de cometer una explotación?', jsonb_build_array('La persona que creyó una promesa.', 'La persona que respondió un mensaje.', 'La persona que sufrió la explotación.', 'La persona que la ejerce.'), 3, 'La responsabilidad es de quien comete la explotación, no de quien la sufre.', 5, 6),
  ('redes-sociales', 'required', 'Alguien te cuenta que una conversación le preocupa. ¿Cómo puedes apoyarle?', jsonb_build_array('Preguntarle por qué no terminó antes el contacto.', 'Escuchar sin juzgar y ofrecerte a buscar ayuda confiable.', 'Escribirle a la otra persona para exigir explicaciones.', 'Publicar el relato para advertir al resto.'), 1, 'Escuchar sin culpar y acompañar a buscar apoyo evita aumentar la exposición o el riesgo.', 5, 7),
  ('redes-sociales', 'required', 'Si alguien está en peligro inmediato, ¿qué indica el material?', jsonb_build_array('Esperar hasta tener una prueba concluyente.', 'Reunirse con la persona que genera preocupación.', 'Contactar los servicios de emergencia del lugar.', 'Publicar la dirección para pedir ayuda en redes.'), 2, 'Ante peligro inmediato, la recomendación es recurrir a los servicios de emergencia locales.', 5, 8)
