values ('redes-sociales', 'Redes sociales y cuidado digital', 'Reconoce riesgos, protege tu información y aprende qué hacer ante un contacto que te incomoda.', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=85', 1, true)
on conflict (slug) do update set title = excluded.title, description = excluded.description, image_url = excluded.image_url, position = excluded.position, is_published = excluded.is_published;

on conflict (topic_slug, quiz_type, position) do update set
  prompt = excluded.prompt,
  options = excluded.options,
  correct_index = excluded.correct_index,
  explanation = excluded.explanation,
  source_slide = excluded.source_slide,
  is_active = true;